    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("mutate(\"hello\", 7)", "hmllo", Mutator.mutate("hello", 7L));
        check("mutate(\"genetic\", 123)", "oenetic", Mutator.mutate("genetic", 123L));
        check("mutate(\"xyz\", 99)", "xoz", Mutator.mutate("xyz", 99L));
        check("mutate(\"hello\", 42) -- mutation may pick the same letter", "hello", Mutator.mutate("hello", 42L));
        check("mutate(\"a\", 1) -- single char string", "a", Mutator.mutate("a", 1L));
        Object len = Mutator.mutate("genetic", 123L) == null ? null : Mutator.mutate("genetic", 123L).length();
        check("length is preserved", 7, len);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
